  ?sensor a brick:Power_Sensor .
  ?sensor brick:isPointOf ?eq .
  ?sensor ref:hasExternalReference ?refnode .
  ?refnode ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?refnode ref:ifcName ?name }
}

